use vstd::prelude::*;

verus! {

    // reverse takes a slice of i32 and returns a new Vec<i32>
    // containing the same elements in reverse order.
    //
    // Ensures:
    //  1. The result has the same length as the input slice.
    //  2. For every index i < len, result[i] == a[len - 1 - i].
    fn reverse(a: &[i32]) -> (result: Vec<i32>)
        ensures
            // same length
            result.len() == a.len(),
            // for all valid indices i, the element is reversed
            forall|i: usize| i < a.len() ==> result.index(i) == a[a.len() - 1 - i],
    {
        let n = a.len();
        let mut res: Vec<i32> = Vec::new();
        // reserve capacity so pushes do not reallocate
        res.reserve(n);

        let mut i: usize = 0;
        // We'll perform n iterations, each time pushing a[n-1-i]
        while i < n
            invariant
                // i never exceeds n
                i <= n,
                // we've pushed exactly i elements so far
                res.len() == i,
                // and those i elements satisfy the reverse property
                forall|j: usize|
                    j < res.len() ==>
                        res.index(j) == a[n - 1 - j],
            decreases n - i,
        {
            let idx: usize = n - 1 - i;
            // push the element from the tail end
            res.push(a[idx]);
            i = i + 1;
        }

        res
    }
}

